# GENERATED by scripts/ops/wavegen.py from ops/waves/turn_easy_poscontrol/spec.yaml -- do not edit by hand.
# Bundle this wave for transfer to the analysis machine.
set -euo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
source "$HERE/../../../scripts/ops/lib/common.sh"

bundle="$RUNROOT/bundles/turn_easy_pc_$(date +%Y%m%d_%H%M%S)"
mkdir -p "$bundle/runroot" "$bundle/_cloud_logs"

# COMPLETION.txt is written by the same checker that gates the read, so the
# bundle cannot claim a completeness its own predicates would reject.
python3 "$DV3OPS_ROOT/scripts/ops/wavecheck.py" \
  "$DV3OPS_ROOT/ops/waves/turn_easy_poscontrol" --runroot "$RUNROOT" \
  > "$bundle/COMPLETION.txt" || true
cat "$bundle/COMPLETION.txt"

for run in adapt_ax1terrgoq1s0_finger_seed1_ckpt500000 adapt_ax1terrgoq1s0_finger_seed2_ckpt500000 adapt_ax1terrgoq1s0_finger_seed3_ckpt500000 adapt_ax1terrgoq1s0_finger_seed4_ckpt500000 adapt_ax1terrgoq1s1_finger_seed1_ckpt500000 adapt_ax1terrgoq1s1_finger_seed2_ckpt500000 adapt_ax1terrgoq1s1_finger_seed3_ckpt500000 adapt_ax1terrgoq1s1_finger_seed4_ckpt500000 adapt_ax1tersgbq1s0_finger_seed1_ckpt500000 adapt_ax1tersgbq1s0_finger_seed2_ckpt500000 adapt_ax1tersgbq1s0_finger_seed3_ckpt500000 adapt_ax1tersgbq1s0_finger_seed4_ckpt500000 adapt_ax1tersgbq1s1_finger_seed1_ckpt500000 adapt_ax1tersgbq1s1_finger_seed2_ckpt500000 adapt_ax1tersgbq1s1_finger_seed3_ckpt500000 adapt_ax1tersgbq1s1_finger_seed4_ckpt500000 adapt_rndte_finger_seed1_ckpt0 adapt_rndte_finger_seed2_ckpt0 adapt_rndte_finger_seed3_ckpt0 adapt_rndte_finger_seed4_ckpt0 adapt_rndte_finger_seed5_ckpt0; do
  if [ -d "$RUNROOT/$run" ]; then
    cp -al "$RUNROOT/$run" "$bundle/runroot/" 2>/dev/null || cp -a "$RUNROOT/$run" "$bundle/runroot/"
  else
    echo "WARN: missing run dir $run" >&2
  fi
done

shopt -s nullglob
for pat in 'adapt_ax1ter*_seed*.out' 'adapt_rndte_*_seed*.out' 'worker_shard*.out'; do
  [ -n "$pat" ] || continue
  for f in "$RUNROOT"/_cloud_logs/$pat; do cp -a "$f" "$bundle/_cloud_logs/"; done
done

cp -a "$HERE/runs.json" "$HERE/RUN_IDS.txt" "$bundle/" 2>/dev/null || true
"$DV3OPS_ROOT/scripts/bundle_manifest.sh" generate "$bundle"
echo "$bundle"
